#!/usr/bin/env python3
"""Turns the JSON of tools/gen/params_wrapper.rb into
internal/web/params_wrapper_gen.go (application controllers only)."""
import json, sys
data = json.load(open(sys.argv[1]))
out = ['// Code generated by tools/gen/params_wrapper_go.py from the Rails app\'s',
       '// ActionController::ParamsWrapper options; DO NOT EDIT.', '', 'package web', '',
       '// paramsWrapper maps a controller path to its wrapper key and include list.',
       'var paramsWrapper = map[string]wrapperOptions{']
for controller, opts in sorted(data.items()):
    if not (controller.startswith('api/') or controller in ('health', 'home')):
        continue
    if opts['format'] != ['json'] or opts['exclude']:
        raise SystemExit('unexpected options for ' + controller)
    inc = ', '.join('"%s"' % i for i in (opts['include'] or []))
    out.append('\t"%s": {Name: "%s", Include: []string{%s}},' % (controller, opts['name'], inc))
out.append('}')
print('\n'.join(out))
